"""Small string utility functions."""


def reverse(s):
    """Return *s* with its characters in reverse order."""
    return s[::-1]


def is_palindrome(s):
    """Return True when *s* reads the same forwards and backwards."""
    return s == reverse(s)

import unittest

from strutil import is_palindrome, reverse


class TestStringUtilities(unittest.TestCase):
    def test_reverse(self):
        self.assertEqual(reverse("hello"), "olleh")
        self.assertEqual(reverse(""), "")

    def test_is_palindrome(self):
        self.assertTrue(is_palindrome("level"))
        self.assertTrue(is_palindrome(""))
        self.assertFalse(is_palindrome("python"))


if __name__ == "__main__":
    unittest.main()
